"""Authored task retrieval corpus. No production profiles or personal data.

Relevance is explicit: two professional descriptions cover the same concrete
task. Other tasks, including tasks in the same profession, are not positives.
The split unit is an entire family, including both profiles and every query.
No documents/queries from the published legacy test are used here.
"""
import hashlib
import json
import re

def family(identifier, role, split, profiles, queries):
    return dict(id=identifier, role=role, split=split, profiles=profiles, queries=queries)

